}

fn digest_walk(root: &Value, schema: &Value, value: &Value, depth: usize) -> Value {
    if depth > MAX_DEPTH {
        return Value::Null;
    }
    let schema = resolve(root, schema);
    if is_secret(schema) {
        return Value::Null;
    }
    if is_private(schema) {
        return Value::String(format!(
            "blake3:{}",
            blake3::hash(value.to_string().as_bytes())
        ));
    }
    match value {
        Value::Object(map) => {
            let mut out = serde_json::Map::new();
            for (key, child) in map {
                let Some(child_schema) = property_schema(root, schema, key) else {
                    // Preserve undeclared keys as-is for audit completeness of
                    // non-schema noise; callers that want projection use
                    // `described_fields` instead.
                    out.insert(key.clone(), child.clone());
                    continue;
                };
                if property_is_secret_only(root, schema, key) {
                    continue;
                }
                if property_is_private_only(root, schema, key) {
                    out.insert(
                        key.clone(),
                        Value::String(format!(
                            "blake3:{}",
                            blake3::hash(child.to_string().as_bytes())
                        )),
                    );
                    continue;
                }
                out.insert(
                    key.clone(),
                    digest_walk(root, child_schema, child, depth + 1),
                );
            }
            Value::Object(out)
        }
        Value::Array(items) => {
            let Some(item_schema) = schema.get("items") else {
                return value.clone();
            };
            Value::Array(
                items
                    .iter()
                    .map(|item| digest_walk(root, item_schema, item, depth + 1))
                    .collect(),
            )
        }
        other => other.clone(),
    }
        "projection file exceeds its size limit"
    );
    let mut bytes = Vec::new();
    let mut reader = file.take(maximum.saturating_add(1));
    let mut chunk = [0_u8; 8192];
    loop {
        let count = reader.read(&mut chunk)?;
        if count == 0 {
            break;
        }
        let length = bytes
            .len()
            .checked_add(count)
            .context("projection file length overflow")?;
        ensure!(
            length as u64 <= maximum,
            "projection file grew beyond its size limit"
        );
        bytes
            .try_reserve_exact(count)
            .context("allocate bounded projection document")?;
        bytes.extend_from_slice(&chunk[..count]);
    }
    Ok(Some(bytes))
}

