copy_one() {
    rel=$1
    excluded "$rel" && return 0
    src=$source_dir/$rel
    [ -e "$src" ] || [ -L "$src" ] || { echo "selected input missing: $rel" >&2; exit 1; }
    mkdir -p "$stage/$(dirname "$rel")"
    if [ -L "$src" ]; then
        resolved=$(realpath "$src")
        case "$resolved/" in
            "$source_dir/"*) ;;
